                    <span class="git-changes">2</span>
                </div>

                <!-- Collaborators -->
                <div class="flex items-center">
                    <img src="data:image/svg+xml,%3Csvg xmlns='' width='24' height='24' viewBox='0 0 24 24'%3E%3Ccircle cx='12' cy='12' r='12' fill='%238B5CF6'/%3E%3C/svg%3E" class="collaborator-avatar" alt="User 1">
