        <!-- Main Content Area -->
        <div class="flex flex-1 overflow-hidden">
            <!-- Left Sidebar -->
            <aside class="flex flex-col border-r" style="width: 280px; background: var(--bg-secondary); border-color: var(--border-color);">
                <!-- Sidebar Tabs -->
                <div class="flex border-b" style="border-color: var(--border-color);">
                    <button class="flex-1 py-3 text-center font-medium border-b-2 transition-all" style="border-color: var(--accent-orange); color: var(--text-primary);">
